import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().process();
    }

    void process() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            int n = Integer.parseInt(br.readLine().trim());
            Circle[] circles = new Circle[n];
            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split("\\s+");
                circles[i] = new Circle(Integer.parseInt(parts[0]),
                                        Integer.parseInt(parts[1]),
                                        Integer.parseInt(parts[2]));
            }

            Set<Point> all = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    List<Point> inter = circles[i].intersect(circles[j]);
                    if (inter != null) all.addAll(inter);
                }
            }

            Map<Point, Integer> pointId = new TreeMap<>();
            List<List<Integer>> adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                List<Double> angles = new ArrayList<>();
                for (int k = 0; k < 3; k++) angles.add(Math.PI * 2 * k / 3.0);
                for (Point p : all) {
                    if (circles[i].contains(p)) {
                        double dx = p.x - circles[i].o.x;
                        double dy = p.y - circles[i].o.y;
                        double alpha = Math.atan2(dy, dx);
                        if (alpha < 0) alpha += 2 * Math.PI;
                        angles.add(alpha);
                    }
                }
                Collections.sort(angles);
                Point dir = new Point(circles[i].r, 0);
                Double[] as = new TreeSet<>(angles).toArray(new Double[0]);
                for (int j = 0; j < as.length; j++) {
                    Point p = circles[i].o.add(dir.rotate(as[j]));
                    getId(p, pointId, adj);
                }
                for (int j = 0; j < as.length; j++) {
                    Point p = circles[i].o.add(dir.rotate(as[j]));
                    Point q = circles[i].o.add(dir.rotate(as[(j + 1) % as.length]));
                    int u = pointId.get(p);
                    int v = pointId.get(q);
                    if (u != v) {
                        adj.get(u).add(v);
                        adj.get(v).add(u);
                    }
                }
            }

            int v = adj.size();
            int e = 0;
            for (List<Integer> list : adj) e += list.size();
            e /= 2;

            int comps = 0;
            boolean[] was = new boolean[v];
            for (int i = 0; i < v; i++) {
                if (!was[i]) {
                    ++comps;
                    dfs(i, was, adj);
                }
            }

            pw.println(1 + comps + e - v);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void dfs(int i, boolean[] was, List<List<Integer>> adj) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(i);
        was[i] = true;
        while (!stack.isEmpty()) {
            int u = stack.pop();
            for (int v : adj.get(u)) {
                if (!was[v]) {
                    was[v] = true;
                    stack.push(v);
                }
            }
        }
    }

    private void getId(Point p, Map<Point, Integer> pointId, List<List<Integer>> adj) {
        if (!pointId.containsKey(p)) {
            int sz = pointId.size();
            pointId.put(p, sz);
            adj.add(new ArrayList<>());
        }
    }

    static class Point implements Comparable<Point> {
        double x, y;
        static final double eps = 1e-8;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        Point rotate(double alpha) {
            double c = Math.cos(alpha), s = Math.sin(alpha);
            return new Point(x * c - y * s, x * s + y * c);
        }
        Point norm() {
            double len = length();
            return scale(1.0 / len);
        }
        Point scale(double f) { return new Point(f * x, f * y); }
        double length() { return Math.sqrt(x * x + y * y); }

        public String toString() { return String.format("%.6f %.6f", x, y); }

        public boolean equals(Object obj) {
            Point o = (Point) obj;
            return Math.abs(x - o.x) < eps && Math.abs(y - o.y) < eps;
        }

        public int compareTo(Point o) {
            if (Math.abs(x - o.x) > eps) return x < o.x ? -1 : 1;
            if (Math.abs(y - o.y) > eps) return y < o.y ? -1 : 1;
            return 0;
        }
    }

    static class Circle {
        Point o;
        double r;
        static final double eps = 1e-8;

        Circle(int x, int y, int r) {
            o = new Point(x, y);
            this.r = r;
        }

        boolean contains(Point p) {
            double dist = p.sub(o).length();
            return Math.abs(dist - r) < eps;
        }

        List<Point> intersect(Circle other) {
            double dx = o.x - other.o.x;
            double dy = o.y - other.o.y;
            double d = Math.sqrt(dx * dx + dy * dy);
            double cos = (r * r + d * d - other.r * other.r) / (2 * r * d);
            if (cos < -1 - eps) return null;
            if (cos < -1) cos = -1;
            if (cos > 1 + eps) return null;
            if (cos > 1) cos = 1;
            List<Point> res = new ArrayList<>();
            double alpha = Math.acos(cos);
            Point dir = other.o.sub(o).norm();
            res.add(o.add(dir.scale(r).rotate(alpha)));
            res.add(o.add(dir.scale(r).rotate(-alpha)));
            return res;
        }
    }
}
